//
document.addEventListener('DOMContentLoaded', function () {
  var metas = document.querySelectorAll('meta[name="description"]');
  for (var i = 0; i < metas.length; i++) { if (metas[i].content.trim()) return; }
  var body = document.querySelector('.post-body, .entry-content, [itemprop="articleBody"]');
  if (!body) return;
  var text = '';
  var ps = body.querySelectorAll('p');
  for (var j = 0; j < ps.length; j++) {
    if (ps[j].closest('figure, figcaption, .kb-related')) continue;
    var t = ps[j].textContent.replace(/\s+/g, ' ').trim();
    if (t.length >= 40) { text = t; break; }
  }
  if (!text) return;
  if (text.length > 160) text = text.slice(0, 157).replace(/\s+\S*$/, '') + '…';
  var meta = metas[0] || document.createElement('meta');
  meta.setAttribute('name', 'description');
  meta.setAttribute('content', text);
  if (!metas[0]) document.head.appendChild(meta);
});
//
